#include <stdio.h>
#include <string.h>

int is_balanced(const char *s) {
    size_t len = strlen(s);
    char *stack = (char *)malloc(len + 1);
    if (!stack) return 0; // allocation failure treated as unbalanced
    size_t top = 0;
    for (size_t i = 0; i < len; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {
                free(stack);
                return 0;
            }
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                free(stack);
                return 0;
            }
        }
    }
    int ok = (top == 0);
    free(stack);
    return ok;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }
    if (is_balanced(argv[1]))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
